    builder = _ClassBuilder(
        cls,
        these,
        slots,
        is_frozen,
        weakref_slot,
        _determine_whether_to_implement(
            cls,
            getstate_setstate,
            auto_detect,
            ("__getstate__", "__setstate__"),
            default=slots,
        ),
        auto_attribs,
        kw_only,
        cache_hash,
        is_exc,
        collect_by_mro,
        on_setattr,
        has_own_setattr,
        field_transformer,
    )

    if _determine_whether_to_implement(
        cls, repr, auto_detect, ("__repr__",)
    ):
        builder.add_repr(repr_ns)

    if str is True:
        builder.add_str()

    eq = _determine_whether_to_implement(
        cls, eq_, auto_detect, ("__eq__", "__ne__")
    )
    if not is_exc and eq is True:
        builder.add_eq()
    if not is_exc and _determine_whether_to_implement(
        cls, order_, auto_detect, ("__lt__", "__le__", "__gt__", "__ge__")
    ):
        builder.add_order()

    if not frozen:
        builder.add_setattr()

    nonlocal hash
    if (
        hash is None
        and auto_detect is True
        and _has_own_attribute(cls, "__hash__")
    ):
        hash = False

    if hash is not True and hash is not False and hash is not None:
        # Can't use `hash in` because 1 == True for example.
        msg = "Invalid value for hash.  Must be True, False, or None."
        raise TypeError(msg)

    if hash is False or (hash is None and eq is False) or is_exc:
        # Don't do anything. Should fall back to __object__'s __hash__
        # which is by id.
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, hashing must be either explicitly or implicitly enabled."
            raise TypeError(msg)
    elif hash is True or (
        hash is None and eq is True and is_frozen is True
    ):
        # Build a __hash__ if told so, or if it's safe.
        builder.add_hash()
    else:
        # Raise TypeError on attempts to hash.
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, hashing must be either explicitly or implicitly enabled."
            raise TypeError(msg)
        builder.make_unhashable()

    if _determine_whether_to_implement(
        cls, init, auto_detect, ("__init__",)
    ):
        builder.add_init()
    else:
        builder.add_attrs_init()
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, init must be True."
            raise TypeError(msg)

    if PY_3_13_PLUS and not _has_own_attribute(cls, "__replace__"):
        builder.add_replace()

    if (
        PY_3_10_PLUS
        and match_args
        and not _has_own_attribute(cls, "__match_args__")
    ):
        builder.add_match_args()

    return builder.build_class()

# maybe_cls's type depends on the usage of the decorator.  It's a class
# if it's used as `@attrs` but `None` if used as `@attrs()`.
if maybe_cls is None:
    return wrap

return wrap(maybe_cls)

def wrap(cls):
    is_frozen = frozen or _has_frozen_base_class(cls)
    is_exc = auto_exc is True and issubclass(cls, BaseException)
    has_own_setattr = auto_detect and _has_own_attribute(
        cls, "__setattr__"
    )

    if has_own_setattr and is_frozen:
        msg = "Can't freeze a class with a custom __setattr__."
        raise ValueError(msg)

    builder = _ClassBuilder(
        cls,
        these,
        slots,
        is_frozen,
        weakref_slot,
        _determine_whether_to_implement(
            cls,
            getstate_setstate,
            auto_detect,
            ("__getstate__", "__setstate__"),
            default=slots,
        ),
        auto_attribs,
        kw_only,
        cache_hash,
        is_exc,
        collect_by_mro,
        on_setattr,
        has_own_setattr,
        field_transformer,
    )

    if _determine_whether_to_implement(
        cls, repr, auto_detect, ("__repr__",)
    ):
        builder.add_repr(repr_ns)

    if str is True:
        builder.add_str()

    eq = _determine_whether_to_implement(
        cls, eq_, auto_detect, ("__eq__", "__ne__")
    )
    if not is_exc and eq is True:
        builder.add_eq()
    if not is_exc and _determine_whether_to_implement(
        cls, order_, auto_detect, ("__lt__", "__le__", "__gt__", "__ge__")
    ):
        builder.add_order()

    if not frozen:
        builder.add_setattr()

    nonlocal hash
    if (
        hash is None
        and auto_detect is True
        and _has_own_attribute(cls, "__hash__")
    ):
        hash = False

    if hash is not True and hash is not False and hash is not None:
        # Can't use `hash in` because 1 == True for example.
        msg = "Invalid value for hash.  Must be True, False, or None."
        raise TypeError(msg)

    if hash is False or (hash is None and eq is False) or is_exc:
        # Don't do anything. Should fall back to __object__'s __hash__
        # which is by id.
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, hashing must be either explicitly or implicitly enabled."
            raise TypeError(msg)
    elif hash is True or (
        hash is None and eq is True and is_frozen is True
    ):
        # Build a __hash__ if told so, or if it's safe.
        builder.add_hash()
    else:
        # Raise TypeError on attempts to hash.
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, hashing must be either explicitly or implicitly enabled."
            raise TypeError(msg)
        builder.make_unhashable()

    if _determine_whether_to_implement(
        cls, init, auto_detect, ("__init__",)
    ):
        builder.add_init()
    else:
        builder.add_attrs_init()
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, init must be True."
            raise TypeError(msg)

    if PY_3_13_PLUS and not _has_own_attribute(cls, "__replace__"):
        builder.add_replace()

    if (
        PY_3_10_PLUS
        and match_args
        and not _has_own_attribute(cls, "__match_args__")
    ):
        builder.add_match_args()

    return builder.build_class()

def _generate_unique_filename(cls: type, func_name: str) -> str:
    """
    Create a "filename" suitable for a function being generated.
    """
    return (
        f"<attrs generated {func_name} {cls.__module__}."
        f"{getattr(cls, '__qualname__', cls.__name__)}>"
    )

def _make_hash_script(
    cls: type, attrs: list[Attribute], frozen: bool, cache_hash: bool
) -> tuple[str, dict]:
    attrs = tuple(
        a for a in attrs if a.hash is True or (a.hash is None and a.eq is True)
    )

    tab = "        "

    type_hash = hash(_generate_unique_filename(cls, "hash"))
    # If eq is custom generated, we need to include the functions in globs
    globs = {}

    hash_def = "def __hash__(self"
    hash_func = "hash(("
    closing_braces = "))"
    if not cache_hash:
        hash_def += "):"
    else:
        hash_def += ", *"

        hash_def += ", _cache_wrapper=__import__('attr._make')._make._CacheHashWrapper):"
        hash_func = "_cache_wrapper(" + hash_func
        closing_braces += ")"

    method_lines = [hash_def]

    def append_hash_computation_lines(prefix, indent):
        """
        Generate the code for actually computing the hash code.
        Below this will either be returned directly or used to compute
        a value which is then cached, depending on the value of cache_hash
        """

        method_lines.extend(
            [
                indent + prefix + hash_func,
                indent + f"        {type_hash},",
            ]
        )

        for a in attrs:
            if a.eq_key:
                cmp_name = f"_{a.name}_key"
                globs[cmp_name] = a.eq_key
                method_lines.append(
                    indent + f"        {cmp_name}(self.{a.name}),"
                )
            else:
                method_lines.append(indent + f"        self.{a.name},")

        method_lines.append(indent + "    " + closing_braces)

    if cache_hash:
        method_lines.append(tab + f"if self.{_HASH_CACHE_FIELD} is None:")
        if frozen:
            append_hash_computation_lines(
                f"object.__setattr__(self, '{_HASH_CACHE_FIELD}', ", tab * 2
            )
            method_lines.append(tab * 2 + ")")  # close __setattr__
        else:
            append_hash_computation_lines(
                f"self.{_HASH_CACHE_FIELD} = ", tab * 2
            )
        method_lines.append(tab + f"return self.{_HASH_CACHE_FIELD}")
    else:
        append_hash_computation_lines("return ", tab)

    script = "\n".join(method_lines)
    return script, globs

def append_hash_computation_lines(prefix, indent):
    """
    Generate the code for actually computing the hash code.
    Below this will either be returned directly or used to compute
    a value which is then cached, depending on the value of cache_hash
    """

    method_lines.extend(
        [
            indent + prefix + hash_func,
            indent + f"        {type_hash},",
        ]
    )

    for a in attrs:
        if a.eq_key:
            cmp_name = f"_{a.name}_key"
            globs[cmp_name] = a.eq_key
            method_lines.append(
                indent + f"        {cmp_name}(self.{a.name}),"
            )
        else:
            method_lines.append(indent + f"        self.{a.name},")

    method_lines.append(indent + "    " + closing_braces)

def _make_eq_script(attrs: list) -> tuple[str, dict]:
    """
    Create __eq__ method for *cls* with *attrs*.
    """
    attrs = [a for a in attrs if a.eq]

    lines = [
        "def __eq__(self, other):",
        "    if other.__class__ is not self.__class__:",
        "        return NotImplemented",
    ]

    globs = {}
    if attrs:
        lines.append("    return  (")
        for a in attrs:
            if a.eq_key:
                cmp_name = f"_{a.name}_key"
                # Add the key function to the global namespace
                # of the evaluated function.
                globs[cmp_name] = a.eq_key
                lines.append(
                    f"        {cmp_name}(self.{a.name}) == {cmp_name}(other.{a.name})"
                )
            else:
                lines.append(f"        self.{a.name} == other.{a.name}")
            if a is not attrs[-1]:
                lines[-1] = f"{lines[-1]} and"
        lines.append("    )")
    else:
        lines.append("    return True")

    script = "\n".join(lines)

    return script, globs

def _make_order(cls, attrs):
    """
    Create ordering methods for *cls* with *attrs*.
    """
    attrs = [a for a in attrs if a.order]

    def attrs_to_tuple(obj):
        """
        Save us some typing.
        """
        return tuple(
            key(value) if key else value
            for value, key in (
                (getattr(obj, a.name), a.order_key) for a in attrs
            )
        )

    def __lt__(self, other):
        """
        Automatically created by attrs.
        """
        if other.__class__ is self.__class__:
            return attrs_to_tuple(self) < attrs_to_tuple(other)

        return NotImplemented

    def __le__(self, other):
        """
        Automatically created by attrs.
        """
        if other.__class__ is self.__class__:
            return attrs_to_tuple(self) <= attrs_to_tuple(other)

        return NotImplemented

    def __gt__(self, other):
        """
        Automatically created by attrs.
        """
        if other.__class__ is self.__class__:
            return attrs_to_tuple(self) > attrs_to_tuple(other)

        return NotImplemented

    def __ge__(self, other):
        """
        Automatically created by attrs.
        """
        if other.__class__ is self.__class__:
            return attrs_to_tuple(self) >= attrs_to_tuple(other)

        return NotImplemented

    return __lt__, __le__, __gt__, __ge__

